vrrp_instance VI_1 {
  interface eth0
  virtual_router_id 51
  priority 100
  advertise_int 1
  authentication {
    auth_type PASS
    auth_pass 1234
  }
  virtual_ipaddress {
    192.168.1.100/24
    192.168.1.101/24
  }
}

vrrp_script chk_nginx {
  script "/usr/bin/pgrep nginx"
  interval 2
  weight -50
}

vrrp_script chk_haproxy {
  script "/usr/bin/pgrep haproxy"
  interval 2
  fall 3
  rise 3
}
